interface TurnstileWidgetApi {
  render(
    container: HTMLElement,
    options: {
      sitekey: string;
      callback(token: string): void;
      "expired-callback"(): void;
      "error-callback"(): void;
    },
  ): string;
  reset(widgetId: string): void;
}

interface Window {
  turnstile?: TurnstileWidgetApi;
}
